/* Original mesh character; historical filename retained for existing bookmarks. */
(function(g){let factory;g.createHiyoriPrototype=function(options={}){if(!g.PlazaHeroModels)throw Error('3Dモデルの読込に失敗しました');factory ||= g.PlazaHeroModels.make(g.THREE,options);return factory.build('girl',{batch(){},shadow(){const m=new g.THREE.Mesh(new g.THREE.CircleGeometry(.36,24),new g.THREE.MeshBasicMaterial({color:'#b8b2a5',transparent:true,opacity:.25,depthWrite:false}));m.rotation.x=-Math.PI/2;m.position.y=.015;return m;}});};})(window);
